// src/entities/BaseEntity.js
function BaseEntity(name) {
  const self = {
    name,
    type: name,
    x: 0,
    y: 0,
    width: 0,
    height: 0,
    addTo(group, index) {
      if (index !== void 0) {
        group.addAt(self.body, index);
        group.addAt(self.skin, index);
      } else {
        group.add(self.body);
        group.add(self.skin);
      }
      self.parent = group;
    },
    setBody(width, height, color) {
      self.body.width = width;
      self.body.height = height;
      self.body.color = color ? color : self.body.color;
    },
    update() {
      self.skin.x = self.body.x;
      self.skin.y = self.body.y;
      self.body.update();
      self.skin.update();
    },
    render(ctx) {
    },
    kill() {
      self.body.detach();
      self.skin.detach();
      self.parent = null;
      self.reserved = false;
    },
    attachProps: defineProps
  };
  function defineProps() {
    Object.defineProperties(self, {
      x: {
        /**
         * @param {number} value
         */
        set(value) {
          self.body.x = value;
        },
        get() {
          return self.body.x;
        }
      },
      y: {
        /**
         * @param {number} value
         */
        set(value) {
          self.body.y = value;
        },
        get() {
          return self.body.y;
        }
      },
      width: {
        /**
         * @param {number} value
         */
        set(value) {
          self.body.width = value;
        },
        get() {
          return self.body.width;
        }
      },
      height: {
        /**
         * @param {number} value
         */
        set(value) {
          self.body.height = value;
        },
        get() {
          return self.body.height;
        }
      },
      scx: {
        /**
         * @param {number} value
         */
        set(value) {
          self.body.scx = value;
        },
        get() {
          return self.body.scx;
        }
      },
      active: {
        get() {
          return Boolean(self.body.parent && self.skin.parent);
        },
        configurable: true,
        enumerable: true
      }
    });
  }
  return self;
}

// src/entities/Actor.js
function Actor(name, width = 0, height = 0, color = "#fff") {
  const body = Rectangle(0, 0, width, height, color);
  body.name = `${name}.body`;
  const o = BaseEntity(name);
  const self = Object.assign(
    o,
    /** @type {TActor<T>} */
    {
      uid: getUID(),
      width,
      height,
      health: 1,
      alpha: 1,
      vx: 0,
      vy: 0,
      sx: 0.8,
      jForce: 2,
      flipH: 1,
      dg: 0.5,
      jg: 0.2,
      g: 0.5,
      body,
      setVisible(bodyVisible, skinVisible) {
        self.body.visible = bodyVisible;
        self.skin.visible = skinVisible;
      },
      update() {
        self.body.update();
        self.updateSkin();
        updateVelocity();
      },
      render(ctx) {
        self.body.render(ctx);
        self.skin.render(ctx);
      },
      addSkin(list) {
        self.skin = MovieClip(list);
        self.skin.name = `${name}.skin`;
      },
      vsPlatforms(colliders) {
        colliders.forEach((platform) => {
          var r1 = self.body;
          var r2 = platform;
          var test = hitTest(r1, r2);
          if (test.hit) {
            if (test.side === "b") {
              self.g = self.dg;
              self.y = self.y - test.overlap.y;
              self.resetVy();
            } else if (test.side === "t") {
              self.y = self.y + test.overlap.y;
              self.resetVy();
            } else if (test.side === "r") {
              self.x = self.x - test.overlap.x;
              self.vx -= self.sx;
            } else if (test.side === "l") {
              self.x = self.x + test.overlap.x;
              self.vx += self.sx;
            }
            self.grounded = test.side === "b";
            self.onWall = test.side === "r" || test.side === "l";
          }
        });
      },
      vsHurts(colliders) {
        for (let i = 0; i < colliders.length; i++) {
          const hurt = colliders[i];
          const r1 = self.body;
          const r2 = hurt;
          const hit = overlap(r1, r2, 1, 0.1);
          if (hit) {
            self.receiveDamage(1, hurt);
            break;
          }
        }
      },
      addSfx(type, x, y) {
        const mc = root.sfxPool.get(type);
        if (!mc) {
          return;
        }
        self.parent.addAt(mc, LAYERS.fg);
        mc.x = x != null ? x : self.x + self.width / 2 - mc.width / 2;
        mc.y = y != null ? y : self.y + self.height - mc.height;
        mc.start(0);
      },
      receiveDamage(amount, from) {
        if (self.dead) {
          return;
        }
        self.health -= amount;
        self.onDamage();
        if (self.health <= 0) {
          self.health = 0;
          self.kill();
        }
      },
      onDamage() {
      },
      doFlipH() {
        self.flipH *= -1;
      },
      kill() {
        self.dead = true;
      },
      reset() {
        if (self.skin) {
          self.skin.stop();
        }
        self.parent = null;
        self.flipH = 1;
        self.health = 1;
        self.dead = false;
        self.moving = false;
        self.grounded = false;
        self.onWall = false;
        self.jumping = false;
        self.falling = false;
        self.attacking = false;
        self.resetVx();
        self.resetVy();
        self.resetGrav();
      },
      detach() {
        self.skin.stop();
        self.skin.detach();
        self.body.detach();
        self.parent = null;
        self.reserved = false;
      },
      resetVx() {
        self.vx = 0;
      },
      resetVy() {
        self.vy = 0;
      },
      voidGrav() {
        self.g = 0;
      },
      resetGrav() {
        self.g = self.dg;
      },
      isFlipH() {
        return self.flipH === -1;
      },
      onLanded() {
      },
      updateSkin() {
        const skin = self.skin;
        if (skin) {
          if (!self.flipHSkinDisabled) {
            skin.scx = self.flipH;
            skin.x = self.body.x + self.body.width;
            if (self.isFlipH()) {
              skin.x = self.body.x + self.body.width;
            } else {
              skin.x = self.body.x;
            }
          } else {
            skin.x = self.body.x;
          }
          skin.y = self.body.y;
          skin.update();
        }
      }
    }
  );
  function updateVelocity() {
    self.vy += self.g;
    self.y += self.vy;
    self.x += self.vx;
    if (!self.grounded && self.vy > 0) {
      self.falling = true;
    }
    if (self.grounded && self.falling) {
      self.onLanded();
      self.falling = false;
    }
  }
  self.attachProps();
  Object.defineProperties(self, {
    active: {
      get() {
        return self.skin.parent && self.body.parent && !self.dead && self.skin.visible;
      },
      configurable: true,
      enumerable: true
    }
  });
  return self;
}

// src/entities/Frog.js
function Frog(name, width, height, color) {
  const o = Actor(name, width, height, color);
  const _detach = o.detach;
  const _kill = o.kill;
  const _addTo = o.addTo;
  const _update = o.update;
  const _reset = o.reset;
  let currentState;
  let jumped = false;
  let fsmIndex = -1;
  let onWallRegistered = false;
  let flyingUp = false;
  let flyingSide = false;
  let damaged = false;
  let itimer = null;
  const fsm = [
    "idle",
    "attack",
    "idle",
    "jump",
    "idle",
    "attack",
    "idle",
    "fly"
  ];
  const self = Object.assign(
    o,
    /** @type {TFrog}*/
    {
      type: name,
      addTo(group, index) {
        _addTo(group, index);
        self.setVisible(false, true);
      },
      update() {
        _update();
        if (self.jumping || flyingSide) {
          self.vx = self.flipH * 0.6;
        }
        if (flyingUp) {
          self.vx = 0;
        }
        if (self.onWall && !onWallRegistered) {
          onWallRegistered = true;
        }
        if (flyingSide) {
          self.vy = 0;
          if (onWallRegistered) {
            self.vx = 0;
            self.g = self.dg;
          }
        }
        if (self.grounded) {
          if (self.jumping) {
            self.jumping = false;
            if (onWallRegistered) {
              self.doFlipH();
              nextFsm(true);
            } else {
              if (!jumped) {
                self.changeState("jump");
              }
            }
          }
          if (flyingSide && onWallRegistered) {
            nextFsm();
          }
          self.vx = 0;
          self.vy = 0;
        }
        self.skin.alpha = Number(!damaged);
      },
      changeState(state) {
        self.attacking = false;
        currentState = state;
        switch (state) {
          case "idle":
            doIdle();
            break;
          case "attack":
            doAttack();
            break;
          case "fly":
            doFly();
            break;
          case "jump":
            doJump();
            break;
        }
      },
      kill() {
        _kill();
        self.setVisible(false, false);
        self.addSfx("blast");
        Sound.play("punch");
        self.detach();
        reset();
        WaitTimer(3, () => {
          root.scene.next();
        });
      },
      detach() {
        reset();
        if (!self.parent) {
          return;
        }
        _detach();
      },
      start() {
        nextFsm(true);
      },
      onDamage() {
        if (damaged) {
          return;
        }
        damaged = true;
        WaitTimer(0.1, () => {
          damaged = false;
        });
        WaitTimer(0.2, () => {
          damaged = true;
        });
        WaitTimer(0.3, () => {
          damaged = false;
        });
      },
      reset() {
        reset();
        _reset();
      },
      weak() {
        return self.active && !self.attacking && self.g;
      },
      smash() {
        return self.active && self.jumping && self.falling;
      },
      onLanded() {
        self.addSfx("impactDusts");
        Sound.play("landed");
      }
    }
  );
  self.addSkin({
    // key should match TFrogSkinType
    idle: { texture: FROG_IDLE },
    attack: { texture: FROG_ATTACK },
    jump: { texture: FROG_JUMP, loop: false },
    fly: { texture: FROG_FLY }
  });
  self.skin.stop();
  function updateFsmIndex() {
    fsmIndex += 1;
    if (fsmIndex > fsm.length - 1) {
      fsmIndex = 0;
    }
  }
  function nextFsm(change = false) {
    onWallRegistered = false;
    flyingUp = false;
    flyingSide = false;
    killTimers2();
    updateFsmIndex();
    const nextState = fsm[fsmIndex];
    if (change) {
      self.changeState(nextState);
    }
    return nextState;
  }
  function doIdle() {
    self.skin.play("idle");
    WaitTimer(3, () => {
      nextFsm(true);
    });
  }
  function doAttack() {
    fsmIndex += 1;
    self.attacking = true;
    self.skin.play("attack");
    addPower();
    WaitTimer(0.5, () => {
      nextFsm(true);
    });
  }
  function doFly() {
    flyingUp = true;
    jump("fly", 0, 0.5);
    flyAttack();
    WaitTimer(2, () => {
      flyingUp = false;
      flyingSide = true;
    });
  }
  function flyAttack() {
    itimer = IntervalTimer(1, () => {
      addPower(false, true);
    });
  }
  function doJump() {
    jumped = true;
    self.skin.play("idle");
    WaitTimer(1, () => {
      jump();
    });
  }
  function jump(anim = "jump", grav = self.jg, force = 3) {
    jumped = false;
    self.jumping = true;
    self.grounded = false;
    self.g = grav;
    self.vy -= force;
    if (!self.moving) {
      self.skin.play(anim);
    }
  }
  function addPower(toVx = true, toVy = false) {
    const mc = root.powerPool.get("fireball");
    if (!self.active || !mc) {
      return;
    }
    mc.addTo(self.parent);
    mc.x = self.x + width / 2;
    mc.y = self.y + self.body.width / 2;
    mc.flipH = self.flipH;
    mc.toVx = toVx;
    mc.toVy = toVy;
    mc.play();
    Sound.play("punch");
  }
  function killTimers2() {
    if (itimer) {
      itimer.kill();
    }
    itimer = null;
  }
  function reset() {
    killTimers2();
    jumped = false;
    onWallRegistered = false;
    flyingUp = false;
    flyingSide = false;
    fsmIndex = -1;
  }
  return self;
}

