// src/entities/Totem.js
function Totem(name, width, height, color) {
  let currentState;
  const o = Actor(name, width, height, color);
  const _detach = o.detach;
  const _kill = o.kill;
  const _addTo = o.addTo;
  const self = Object.assign(
    o,
    /** @type {TTotem}*/
    {
      type: name,
      attackTime: 1,
      addTo(group, index) {
        _addTo(group, index);
        self.setVisible(false, true);
      },
      update() {
        self.body.update();
        self.updateSkin();
      },
      changeState(state) {
        currentState = state;
        switch (state) {
          case "idle":
            doIdle();
            break;
          case "attack":
            doAttack();
            break;
        }
      },
      vsPlatforms() {
      },
      kill() {
        _kill();
        self.setVisible(false, false);
        self.addSfx("blast");
        Sound.play("punch");
        WaitTimer(1, self.detach);
      },
      detach() {
        if (!self.parent) {
          return;
        }
        _detach();
      }
    }
  );
  self.addSkin({
    // key should match TTotemSkinType
    idle: { texture: TOTEM_IDLE, loop: false },
    attack: { texture: TOTEM_ATTACK, loop: false }
  });
  self.skin.stop();
  self.skin.onComplete = (animName) => {
    if (animName === "attack") {
      self.changeState("idle");
      addPower();
    }
  };
  function doIdle() {
    self.skin.play("idle");
    WaitTimer(self.attackTime, doAttack);
  }
  function doAttack() {
    self.skin.play("attack");
  }
  function addPower() {
    const mc = root.powerPool.get("fireball");
    if (!mc) {
      return;
    }
    const offsetX = self.isFlipH() ? 8 : 0;
    mc.addTo(self.parent);
    mc.x = self.x + self.body.width / 2 - offsetX;
    mc.y = self.y + self.body.width / 2 + 4;
    mc.flipH = self.flipH;
    mc.play();
    Sound.play("punch");
  }
  return self;
}

// src/entities/ActorPool.js
function ActorPool() {
  let player;
  let frog;
  let totems = {};
  const self = {
    init() {
      initPlayer();
      initTotems();
      initFrog();
    },
    getPlayer() {
      return player;
    },
    getTotem() {
      const pool2 = totems["totem"].pool;
      let extractedTotem = null;
      for (let i = 0; i < pool2.length; i++) {
        const totem = pool2[i];
        if (!totem.active) {
          extractedTotem = totem;
          break;
        }
      }
      return extractedTotem;
    },
    getFrog() {
      return frog;
    },
    detach() {
      player.detach();
      player.reset();
      detachTotems();
      frog.detach();
      frog.reset();
    }
  };
  self.init();
  function initPlayer() {
    player = Player("player", 8, 8);
  }
  function initTotems() {
    addToBasket("totem", { max: 4, pool: [] });
    for (let name in totems) {
      const props = totems[name];
      const max = props.max;
      const pool2 = props.pool;
      for (let i = 0; i < max; i++) {
        const id = `${name}_${i}`;
        const totem = Totem(id, 8, 8);
        pool2.push(totem);
      }
    }
  }
  function initFrog() {
    frog = Frog("frog", 8, 8);
  }
  function detachTotems() {
    for (let name in totems) {
      const props = totems[name];
      const pool2 = props.pool;
      pool2.forEach((totem) => {
        totem.detach();
        totem.reset();
      });
    }
  }
  function addToBasket(name, data) {
    totems[name] = data;
  }
  return self;
}

