// src/entities/StaticEntity.js
function StaticEntity(name, texture) {
  const o = BaseEntity(name);
  const _kill = o.kill;
  const self = Object.assign(
    o,
    /** @type {TStaticEntity} */
    {
      loop: true,
      addBody() {
        self.body = Rectangle(0, 0, texture.w, texture.h);
        self.body.name = `${name}.body`;
        self.body.visible = false;
      },
      addSkin() {
        self.skin = AnimatedSprite(texture, false, self.loop);
        self.skin.name = `${name}.skin`;
        self.skin.onComplete = self.onComplete;
      },
      play() {
        self.skin.visible = true;
        self.skin.start();
      },
      stop(frameIndex) {
        self.skin.stop(frameIndex);
      },
      kill() {
        self.skin.stop();
        _kill();
      }
    }
  );
  return self;
}

// src/entities/PowerBase.js
function PowerBase(name, texture) {
  const o = StaticEntity(name, texture);
  const self = Object.assign(
    o,
    /** @type {TPowerBase} */
    {
      name,
      type: "power",
      flipH: 1,
      sx: 1,
      sy: 1,
      vx: 0,
      vy: 0,
      scx: 1,
      vsPlatforms(colliders) {
        if (!self.allowHit) {
          return;
        }
        for (let i = 0; i < colliders.length; i++) {
          if (!self.active) {
            break;
          }
          const platform = colliders[i];
          const r1 = self.body;
          const r2 = platform;
          const hit = overlap(r1, r2);
          if (hit) {
            self.onHitPlatform(platform);
            self.kill();
          }
        }
      },
      onHitPlatform(platform) {
      }
    }
  );
  self.attachProps();
  return self;
}

// src/entities/PowerFireBall.js
function PowerFireBall(name, texture) {
  const o = PowerBase(name, texture);
  const _update = o.update;
  const _kill = o.kill;
  const self = Object.assign(
    o,
    /** @type {Partial<TPowerBase>}*/
    {
      toVx: true,
      update() {
        if (!self.active) {
          return;
        }
        _update();
        if (self.toVx) {
          self.vx = self.flipH * self.sx;
          self.x += self.vx;
        }
        if (self.toVy) {
          self.vx = 0;
          self.vy = self.sy;
          self.y += self.vy;
        }
      },
      onHitPlatform(platform) {
        addSfx();
      },
      vsPlayer(player) {
        if (!self.active || !player.active) {
          return;
        }
        const r1 = self.body;
        const r2 = player.body;
        const hit = overlap(r1, r2, 0.5, 0.5);
        if (hit) {
          player.receiveDamage(1, self);
        }
      },
      kill() {
        self.toVx = true;
        self.toVy = false;
        _kill();
      }
    }
  );
  self.allowHit = true;
  self.addBody();
  self.addSkin();
  function addSfx() {
    const mc = root.sfxPool.get("fireballImpact");
    if (!mc) {
      return;
    }
    mc.x = self.flipH === -1 ? self.x + self.width : self.x;
    mc.y = self.y;
    mc.scx = self.flipH;
    mc.start();
    self.parent.add(mc);
  }
  return self;
}

// src/entities/PowerTailWhip.js
function PowerTailWhip(name, texture) {
  const o = PowerBase(name, texture);
  const _update = o.update;
  const self = Object.assign(
    o,
    /** @type {Partial<TPowerBase>}*/
    {
      update() {
        if (!self.active) {
          return;
        }
        _update();
        self.skin.scx = self.body.scx;
        if (self.body.scx < 0) {
          self.skin.x = self.x + self.skin.width;
        } else {
          self.skin.x = self.x;
        }
        self.skin.y = self.body.y - self.skin.height + self.body.height;
      },
      onComplete(name2) {
        self.kill();
      },
      vsPlatforms() {
      },
      vsTotems(totems) {
        for (let i = 0; i < totems.length; i++) {
          const totem = totems[i];
          const r1 = self.body;
          const r2 = totem.body;
          const hit = overlap(r1, r2, 0.8, 0.8);
          if (hit && totem.active && allowHit()) {
            totem.receiveDamage(1, self);
          }
        }
      },
      vsTorches(torches, player) {
        for (let i = 0; i < torches.length; i++) {
          const torch = torches[i];
          const r1 = self.body;
          const r2 = torch.body;
          const hit = overlap(r1, r2, 0.8, 0.8);
          if (hit && allowHit() && !player.swung) {
            player.doSwing();
          }
        }
      },
      vsFrog(frog) {
        if (!frog) {
          return;
        }
        const r1 = self.body;
        const r2 = frog.body;
        const hit = overlap(r1, r2);
        if (hit && frog.weak() && allowHit()) {
          frog.receiveDamage(1, self);
        }
      }
    }
  );
  self.loop = false;
  self.addBody();
  self.addSkin();
  self.body.height = 8;
  function allowHit() {
    return self.skin.currentFrame >= self.skin.totalFrames - 1;
  }
  return self;
}

// src/entities/PowerPool.js
var MAX_POWER_FIRE_BALL = 8;
var MAX_POWER_TAIL_WHIP = 1;
function PowerPool() {
  let uid = 0;
  const powers = {};
  const updaters = {};
  const self = {
    init() {
      addToBasket("fireball", { max: MAX_POWER_FIRE_BALL, pool: [] });
      addToBasket("tailwhip", { max: MAX_POWER_TAIL_WHIP, pool: [] });
      for (let key in powers) {
        const bname = (
          /** @type {TPowerType}*/
          key
        );
        const props = powers[bname];
        const max = props.max;
        const pool2 = props.pool;
        for (let i = 0; i < max; i++) {
          const newName = `${bname}_${i}`;
          switch (bname) {
            case "fireball":
              pool2.push(PowerFireBall(newName, POWER_FIRE_BALL));
              break;
            case "tailwhip":
              pool2.push(PowerTailWhip(newName, TAIL_WHIP));
              break;
          }
        }
      }
    },
    update(group, platforms, totems, player, torches, frog) {
      for (let id in updaters) {
        const mc = updaters[id];
        if (mc.active) {
          mc.update();
          mc.vsPlatforms(platforms);
          if (mc.vsTotems) {
            mc.vsTotems(totems);
          }
          if (mc.vsPlayer) {
            mc.vsPlayer(player);
          }
          if (mc.vsTorches) {
            mc.vsTorches(torches, player);
          }
          if (mc.vsFrog) {
            mc.vsFrog(frog);
          }
        } else {
          delete updaters[id];
        }
      }
    },
    render(ctx) {
      for (let id in updaters) {
        const mc = updaters[id];
        if (mc.active) {
          mc.render(ctx);
        }
      }
    },
    get(name) {
      const pool2 = powers[name].pool;
      let mc;
      for (let i = 0; i < pool2.length; i++) {
        const _mc = pool2[i];
        if (!_mc.active && !_mc.reserved) {
          mc = _mc;
          uid += 1;
          updaters[uid] = mc;
          mc.reserved = true;
          break;
        }
      }
      return mc;
    },
    detach() {
      for (let key in powers) {
        const bname = (
          /** @type {TPowerType}*/
          key
        );
        const props = powers[bname];
        const pool2 = props.pool;
        pool2.forEach((mc) => {
          mc.kill();
        });
      }
      clearUpdaters();
    }
  };
  self.init();
  function clearUpdaters() {
    for (let id in updaters) {
      delete updaters[id];
    }
  }
  function addToBasket(name, data) {
    powers[name] = data;
  }
  return self;
}

