// src/entities/SfxBase.js
function SfxBase(name, texture, loop = false) {
  const o = AnimatedSprite(texture, false, loop);
  const self = Object.assign(
    o,
    /** @type {TSfxBase}*/
    {
      name,
      onComplete(name2) {
        self.kill();
      },
      kill() {
        self.stop();
        self.detach();
        self.reserved = false;
      }
    }
  );
  self.visible = true;
  Object.defineProperties(self, {
    active: {
      get() {
        return self.parent;
      }
    }
  });
  return self;
}

// src/entities/SfxPool.js
function SfxPool() {
  let uid = 0;
  const basket = {};
  const updaters = {};
  const self = {
    init() {
      addToBasket("impactDusts", { max: 3, pool: [] });
      addToBasket("fireballImpact", { max: 20, pool: [] });
      addToBasket("love", { max: 1, pool: [] });
      addToBasket("blast", { max: 3, pool: [] });
      for (let key in basket) {
        const bname = (
          /** @type {TSfxType}*/
          key
        );
        const props = basket[bname];
        const max = props.max;
        const pool2 = props.pool;
        for (let i = 0; i < max; i++) {
          const newName = `${bname}_${i}`;
          switch (bname) {
            case "impactDusts":
              pool2.push(SfxBase(newName, IMPACT_DUSTS_SFX));
              break;
            case "fireballImpact":
              pool2.push(SfxBase(newName, FIRE_BALL_IMPACT_SFX));
              break;
            case "love":
              pool2.push(SfxBase(newName, LOVE, true));
              break;
            case "blast":
              pool2.push(SfxBase(newName, BLAST));
              break;
          }
        }
      }
    },
    update() {
      for (let id in updaters) {
        const mc = updaters[id];
        if (mc.active) {
          mc.update();
        } else {
          delete updaters[id];
        }
      }
    },
    get(name) {
      const pool2 = basket[name].pool;
      let mc;
      for (let i = 0; i < pool2.length; i++) {
        const _mc = pool2[i];
        if (!_mc.active && !_mc.reserved) {
          mc = _mc;
          uid += 1;
          updaters[uid] = mc;
          mc.reserved = true;
          break;
        }
      }
      return mc;
    },
    detach() {
      for (let key in basket) {
        const bname = (
          /** @type {TSfxType}*/
          key
        );
        const props = basket[bname];
        const pool2 = props.pool;
        pool2.forEach((mc) => {
          mc.kill();
        });
      }
      clearUpdaters();
    }
  };
  self.init();
  function clearUpdaters() {
    for (let id in updaters) {
      delete updaters[id];
    }
  }
  function addToBasket(name, data) {
    basket[name] = data;
  }
  return self;
}

// src/Resizer.js
function Resizer(layers, dimension) {
  let defaultSize = 512;
  let fullScreen = true;
  const resize = () => {
    const windowWidth = window.innerWidth;
    const windowHeight = window.innerHeight;
    const availableRatio = windowWidth / windowHeight;
    const canvasRatio = dimension.width / dimension.height;
    let appliedWidth = 0;
    let appliedHeight = 0;
    if (availableRatio <= canvasRatio) {
      appliedWidth = windowWidth;
      appliedHeight = appliedWidth / canvasRatio;
    } else {
      appliedHeight = windowHeight;
      appliedWidth = appliedHeight * canvasRatio;
    }
    layers.forEach((layer) => {
      const canvas = layer.canvas;
      if (fullScreen) {
        canvas.style.width = toPx(appliedWidth);
        canvas.style.height = toPx(appliedHeight);
      } else {
        canvas.style.width = toPx(defaultSize);
        canvas.style.height = toPx(defaultSize);
      }
    });
  };
  window.onresize = resize;
  resize();
}

