// src/entities/Boulder.js
function Boulder(name, width, height, color) {
  let currentState;
  const o = Actor(name, width, height, color);
  const _detach = o.detach;
  const _kill = o.kill;
  const _addTo = o.addTo;
  const _update = o.update;
  let started = false;
  let stopped = false;
  const self = Object.assign(
    o,
    /** @type {TBoulder}*/
    {
      startTime: 4,
      type: "boulder",
      sx: 0.3,
      addTo(group, index) {
        _addTo(group, index);
        self.setVisible(false, true);
      },
      update() {
        _update();
        updateMovement();
      },
      changeState(state) {
        currentState = state;
        switch (state) {
          case "idle":
            doIdle();
            break;
          case "roll":
            doRoll();
            break;
          case "stop":
            doIdle(true);
            break;
        }
      },
      kill() {
        _kill();
        self.setVisible(false, false);
      },
      detach() {
        if (!self.parent) {
          return;
        }
        _detach();
      },
      start() {
        if (!started) {
          started = true;
        }
        const time = started ? 0.5 : self.startTime;
        WaitTimer(time, startRoll);
      },
      vsReversers(colliders) {
        for (let i = 0; i < colliders.length; i++) {
          const reverser = colliders[i];
          const r1 = self.body;
          const r2 = reverser;
          const hit = overlap(r1, r2);
          if (hit) {
            self.flipH = reverser.side;
            break;
          }
        }
      },
      vsStoppers(colliders) {
        if (stopped) {
          return;
        }
        for (let i = 0; i < colliders.length; i++) {
          const stopper = colliders[i];
          const r1 = self.body;
          const r2 = stopper;
          const hit = overlap(r1, r2);
          if (hit) {
            self.changeState("stop");
            break;
          }
        }
      },
      onTrigger(from, delay) {
        self.reserved = false;
        self.startTime = delay;
        self.changeState("idle");
      },
      onLanded() {
        self.addSfx("impactDusts");
      }
    }
  );
  self.addSkin({
    // key should match TBoulderSkinType
    roll: { texture: BOULDER }
  });
  initState();
  function updateMovement() {
    if (self.moving) {
      self.vx = self.flipH * self.sx;
    } else {
      self.vx = 0;
    }
    if (!self.grounded && started) {
      self.changeState("idle");
    }
  }
  function initState() {
    self.skin.stop();
    self.moving = false;
  }
  function doIdle(stop = false) {
    initState();
    if (!stop) {
      self.start();
    } else {
      stopped = true;
    }
  }
  function startRoll() {
    self.changeState("roll");
  }
  function doRoll() {
    self.moving = true;
    self.skin.play("roll");
  }
  return self;
}

// src/entities/Reverser.js
function Reverser(name, x, y, width, height) {
  const o = Rectangle(x, y, width, height);
  const self = Object.assign(
    o,
    /** @type {TReverser}*/
    {
      name,
      side: 1
    }
  );
  return self;
}

// src/entities/Trigger.js
function Trigger(nodeList, width, height, color) {
  let nodes = nodeList;
  let entitiesTriggered = nodes.map(() => false);
  const o = Rectangle(0, 0, width, height, color);
  const self = Object.assign(
    o,
    /** @type {TTrigger}*/
    {
      nodes,
      width,
      height,
      delay: 0,
      register(index) {
        entitiesTriggered[index] = true;
      },
      isJobDone() {
        return !entitiesTriggered.includes(false);
      },
      kill() {
        self.detach();
      }
    }
  );
  return self;
}

// lib/fonts/BitmapFont.js
function BitmapFont(fontTexture, fontFrames, fontTilesetColumns, text, gap = 1) {
  const o = DisplayObject();
  const _render = o.render;
  let _text = text;
  let _gap = gap;
  let buffer = toCanvasPool(String(o.uid));
  let bcanvas = buffer.canvas;
  let bctx = buffer.ctx;
  const self = Object.assign(
    o,
    /** @type {TBitmapFont}*/
    {
      text: _text,
      texture: fontTexture,
      render(ctx) {
        if (!self.visible || !self.texture) {
          return;
        }
        if (buffer.cached) {
          renderProps(self, ctx);
          ctx.drawImage(bcanvas, 0, 0);
          return;
        }
        buffer.cached = true;
        const frames = getTextFrames();
        const w = fontTexture.w;
        const col = fontTilesetColumns;
        bcanvas.width = ctx.canvas.width;
        bcanvas.height = ctx.canvas.height;
        frames.forEach((frame, i) => {
          const id = frame.id;
          let tx = i % col * w;
          if (i) {
            const prevFramesWidth = frames.map((val) => val.w).filter((_, j) => j < i);
            const totalPrevFramesWidth = prevFramesWidth.reduce((a, b) => a + b, 0);
            tx = totalPrevFramesWidth + self.gap * i;
          }
          const ty = 0;
          renderTexture(bctx, self.texture, id, tx, ty);
        });
        renderProps(self, bctx);
      },
      destroy() {
        dropCanvasPool(String(o.uid));
      }
    }
  );
  function getTextFrames() {
    const texts = _text.split("");
    const letters = fontFrames.map((val) => val[0]);
    const letterWidths = fontFrames.map((val) => val[1]);
    const frames = texts.map((letter) => {
      const letterIndex = letters.indexOf(letter);
      const letterWidth = letterWidths[letterIndex];
      return { id: letterIndex, w: letterWidth, l: letter };
    });
    return frames;
  }
  if (fontTexture) {
    self.width = fontTexture.w;
    self.height = fontTexture.h;
  }
  function recreateBuffer() {
    buffer = toCanvasPool(String(o.uid));
    bcanvas = buffer.canvas;
    bctx = buffer.ctx;
  }
  Object.defineProperties(self, {
    text: {
      /**
       * @param {string} value
       */
      set(value) {
        if (_text === value) {
          return;
        }
        _text = value;
        self.destroy();
        recreateBuffer();
      },
      get() {
        return _text;
      }
    },
    gap: {
      /**
       * @param {number} value
       */
      set(value) {
        _gap = value;
        self.destroy();
        recreateBuffer();
      },
      get() {
        return _gap;
      }
    }
  });
  return self;
}

